def _dst(y, mo, d):
    import datetime as _dt
    m1 = _dt.date(y, 3, 1)
    ms = 1 + ((6 - m1.weekday()) % 7) + 7
    n1 = _dt.date(y, 11, 1)
    ne = 1 + ((6 - n1.weekday()) % 7)
    if mo < 3 or mo > 11:
        return False
    if 3 < mo < 11:
        return True
    if mo == 3:
        return d >= ms
    return d < ne


def _et_minutes(bars):
    """Minute-of-day in America/New_York for every bar. UTC in, ET out."""
    off = {}
    out = []
    for b in bars:
        ts = str(b["t"])
        day = ts[:10]
        o = off.get(day)
        if o is None:
            o = -4 if _dst(int(ts[0:4]), int(ts[5:7]), int(ts[8:10])) else -5
            off[day] = o
        out.append((int(ts[11:13]) + o) * 60 + int(ts[14:16]))
    return out


def _grid_size(px, mult):
    """Osler's round-number grid, sized by price tier."""
    if px < 20.0:
        g = 0.10
    elif px < 100.0:
        g = 0.50
    else:
        g = 1.00
    return g * mult


def family_init(ctx):
    ctx.et = _et_minutes(ctx.bars)
    ctx._lvl = None


def signal(ctx, i):
    import math
    lb = int(ctx.p.lookback)
    if i < lb + 1:
        return 0
    h, l, c = ctx.h[i], ctx.l[i], ctx.c[i]
    c1 = ctx.c[i - 1]
    if None in (h, l, c, c1):
        return 0
    rng = h - l
    if rng <= 0:
        return 0
    g = _grid_size(c, float(ctx.p.g_mult))
    if g <= 0:
        return 0
    clp = float(ctx.p.clp)

    # ---- SHORT: nearest untested grid level ABOVE the close was poked ----
    short_ok = False
    rs = (math.floor(c / g + 1e-9) + 1.0) * g
    if h >= rs and c1 < rs and (c - l) / rng <= clp:
        short_ok = True
        for k in range(1, lb + 1):
            x = ctx.c[i - k]
            if x is None or x >= rs:
                short_ok = False
                break

    # ---- LONG: nearest untested grid level BELOW the close was poked ----
    long_ok = False
    rl = (math.ceil(c / g - 1e-9) - 1.0) * g
    if l <= rl and c1 > rl and (h - c) / rng <= clp:
        long_ok = True
        for k in range(1, lb + 1):
            x = ctx.c[i - k]
            if x is None or x <= rl:
                long_ok = False
                break

    if short_ok and long_ok:
        return 0                      # a bar straddling two levels says nothing
    if short_ok:
        if not ctx.positions:
            ctx._lvl = (rs, g, -1)
        return -1
    if long_ok:
        if not ctx.positions:
            ctx._lvl = (rl, g, 1)
        return 1
    return 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    if ctx.et[i] >= int(ctx.p.flat_min):
        return True                   # flat before the bell
    lv = ctx._lvl
    if lv is None:
        return False
    r, g, d = lv
    if d < 0:
        lo = ctx.l[i]
        return lo is not None and lo <= r - g
    hi = ctx.h[i]
    return hi is not None and hi >= r + g
